function foldsToEqual(s: string): boolean {
  const d = Array.from(s, Number);
  for (let len = d.length; len > 2; len--) {
    for (let i = 0; i < len - 1; i++) d[i] = (d[i] + d[i + 1]) % 10;
  }
  return d[0] === d[1];
}

