function foldsToEqual(s: string): boolean {
  const d = Array.from(s, Number);
  const m = d.length - 2;
  // row m of Pascal's triangle, mod 10
  const row = [1];
  for (let k = 1; k <= m; k++) {
    row.push(1);
    for (let i = k - 1; i > 0; i--) row[i] = (row[i] + row[i - 1]) % 10;
  }
  let left = 0, right = 0;
  for (let i = 0; i <= m; i++) {
    left = (left + row[i] * d[i]) % 10;
    right = (right + row[i] * d[i + 1]) % 10;
  }
  return left === right;
}

