        d = [int(c) for c in s]
        m = len(d) - 2
        row = [1]  # row m of Pascal's triangle, mod 10
        for _ in range(m):
            row = [1] + [(row[i] + row[i + 1]) % 10 for i in range(len(row) - 1)] + [1]
        left = sum(w * d[i] for i, w in enumerate(row)) % 10
        right = sum(w * d[i + 1] for i, w in enumerate(row)) % 10
        return left == right

